fn is_palindrome(text: Vec<char>) -> bool {
    // Helper function to lowercase ASCII uppercase letters only
    fn to_ascii_lowercase(c: char) -> char {
        if ('A'..='Z').contains(&c) {
            ((c as u8) + 32) as char
        } else {
            c
        }
    }

    let len = text.len();
    for i in 0..len / 2 {
        if to_ascii_lowercase(text[i]) != to_ascii_lowercase(text[len - 1 - i]) {
            return false;
        }
    }
    true
}